const query=ref(''), message=ref(''), recording=ref(false), commonDiagnoses=ref<any[]>([]), diagnosisLoading=ref(true), diagnosisError=ref('')
const resourceModal=ref('')
const patient=ref<any>({name:'',age:'',gender:'',id:'',phone:'',allergies:[],conditions:[],last_visit:''})
const nav=[['Home',Home,''],['Patient',UserRound,'Identify & Manage'],['Notifications',Bell,'Alerts & Preferences'],['AI Models',Bot,'Select & Configure'],['Statistics',BarChart3,'Insights & Reports'],['Treatment Templates',LayoutTemplate,'Plan & Prescribe']]
const filtered=computed(()=>commonDiagnoses.value.filter(d=>(d.name||d.title||'').toLowerCase().includes(query.value.toLowerCase())))
async function loadCommonDiagnoses(){diagnosisLoading.value=true;diagnosisError.value='';try{commonDiagnoses.value=await api<any[]>('/diagnoses/common')}catch(e:any){diagnosisError.value=e?.data?.message||'Could not load common diagnoses.';commonDiagnoses.value=[]}finally{diagnosisLoading.value=false}}
onMounted(loadCommonDiagnoses)
function openNav(label:string){if(label==='Home')return;activeModal.value=label;mobileLeft.value=false}
function send(){if(!message.value.trim())return;message.value=''}
function selectPatient(p:any){patient.value={...patient.value,...p};activeModal.value=''}
