l='medicine'"><Pill :size="21"/><b>Search Medicines</b><span>Brand / Generic</span></button><button class="utility" @click="resourceModal='diagnosis'"><Search :size="21"/><b>Search Diagnosis</b><span>Available in area</span></button><button class="utility" @click="resourceModal='tests'"><FlaskConical :size="21"/><b>Order Tests</b><span>Lab / Imaging</span></button></div></div></div>
